Here is a complete C program that utilizes a user-defined structure `Employee`, dynamic memory allocation via pointers, and functions to store and display employee details:

```c
#include <stdio.h>
#include <stdlib.h>

// Defining the user-defined structure
struct Employee {
    int emp_id;
    char name[50];
    float salary;
    char department[30];
};

int main() {
    int n, i;
    struct Employee *empPtr; // Pointer to structure

    printf("Enter the number of employees: ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("Invalid number of employees.\n");
        return 1;
    }

    // Dynamically allocating memory for n employees
    empPtr = (struct Employee *)malloc(n * sizeof(struct Employee));
    if (empPtr == NULL) {
        printf("Memory allocation failed!\n");
        return 1;
    }

    // Reading employee information using pointer notation
    for (i = 0; i < n; i++) {
        printf("\nEnter details for Employee %d:\n", i + 1);
        printf("Employee ID: ");
        scanf("%d", &(empPtr + i)->emp_id);
        printf("Name: ");
        scanf(" %[^\n]s", (empPtr + i)->name); // Reads space-separated names
        printf("Salary: ");
        scanf("%f", &(empPtr + i)->salary);
        printf("Department: ");
        scanf(" %[^\n]s", (empPtr + i)->department);
    }

    // Displaying employee information using pointer notation
    printf("\n--- Employee Database ---\n");
    printf("%-10s %-20s %-12s %-15s\n", "ID", "Name", "Salary", "Department");
    printf("------------------------------------------------------------\n");
    for (i = 0; i < n; i++) {
        printf("%-10d %-20s $%-11.2f %-15s\n",
               (empPtr + i)->emp_id,
               (empPtr + i)->name,
               (empPtr + i)->salary,
               (empPtr + i)->department);
    }

    // Deallocating dynamically allocated memory
    free(empPtr);
    return 0;
}
```

### Deletion from a Doubly Linked List (DLL)

In a Doubly Linked List, every node has reference pointers to both its predecessor (`prev`) and successor (`next`). Deleting a node involves updating these surrounding pointers to bypass the deleted node, followed by freeing its allocated memory.

### Pointer Adjustment Diagrams

#### 1. Before Deletion of Node `del`

```text
+------+        +------+        +------+
... <->| prev |<------>|  del |<------>| next |<-> ...
       +------+        +------+        +------+

```

#### 2. After Deletion (Pointers adjusted around `del`)

```text
+------+                        +------+
... <->| prev |<---------------------->| next |<-> ...
       +------+

```

---

### C Routine for Deletion

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* prev;
    struct Node* next;
};

void deleteNode(struct Node** head_ref, struct Node* del) {
    // Base Case
    if (*head_ref == NULL || del == NULL) {
        return;
    }

    // Case 1: If the node to be deleted is the head node
    if (*head_ref == del) {
        *head_ref = del->next;
    }

    // Case 2: Update the prev pointer of the successor (next) node
    if (del->next != NULL) {
        del->next->prev = del->prev;
    }

    // Case 3: Update the next pointer of the predecessor (prev) node
    if (del->prev != NULL) {
        del->prev->next = del->next;
    }

    // Free memory of the deleted node
    free(del);
}
```

### AVL Tree Rotations
An AVL tree maintains balanced heights by executing rotations when the balance factor of any node ($BF = Height(LeftSub) - Height(RightSub)$) falls out of the interval $[-1, 1]$.

There are four basic types of rotation combinations:

#### 1. Single Right Rotation (LL Rotation)
Used when a node is added to the left subtree of the left child.

```text
z (BF=2)               y
      /                      / \
     y           ==>        x   z
    /
   x

```

#### 2. Single Left Rotation (RR Rotation)
Used when a node is added to the right subtree of the right child.

```text
z (BF=-2)                y
      \                      / \
       y         ==>        z   x
        \
         x

```

#### 3. Left-Right Rotation (LR Rotation)
Used when a node is added to the right subtree of the left child (Double rotation: Left-Rotate $y$, then Right-Rotate $z$).

```text
z (BF=2)             z (BF=2)             x
      /                    /                    / \
     y         ==>        x          ==>       y   z
      \                  /
       x                y

```

#### 4. Right-Left Rotation (RL Rotation)
Used when a node is added to the left subtree of the right child (Double rotation: Right-Rotate $y$, then Left-Rotate $z$).

```text
z (BF=-2)            z (BF=-2)             x
      \                    \
       y       ==>          x        ==>       z   y
      /                      \
     x                        y

```

---

### C Routines for Rotations

```c
struct Node {
    int key;
    struct Node *left, *right;
    int height;
};

int getHeight(struct Node *n) {
    return (n == NULL) ? 0 : n->height;
}

int max(int a, int b) {
    return (a > b) ? a : b;
}

// Left Rotate (RR rotation helper)
struct Node* leftRotate(struct Node *x) {
    struct Node *y = x->right;
    struct Node *T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = max(getHeight(x->left), getHeight(x->right)) + 1;
    y->height = max(getHeight(y->left), getHeight(y->right)) + 1;

    return y;
}

// Right Rotate (LL rotation helper)
struct Node* rightRotate(struct Node *y) {
    struct Node *x = y->left;
    struct Node *T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = max(getHeight(y->left), getHeight(y->right)) + 1;
    x->height = max(getHeight(x->left), getHeight(x->right)) + 1;

    return x;
}
```
